# Publish this repo's rules, skills, and Pi extensions into user-level agent config folders.
# Additive by default: existing non-link files/dirs are left untouched; our own
# links and generated files are refreshed. Safe to re-run anytime (e.g. after
# `git pull`). Pass -Clean to wipe managed folders and republish instead.
#
# Run from an elevated PowerShell (Administrator) or with Developer Mode enabled
# so that creating symbolic links is permitted.
[CmdletBinding()]
param(
    # Remove everything from managed skill/rule/extension folders before republishing.
    [switch] $Clean,
    # Skip the -Clean confirmation prompt.
    [switch] $Yes
)

$ErrorActionPreference = 'Stop'

$RepoRoot = Split-Path -Parent $PSScriptRoot
$RulesSrc = Join-Path $RepoRoot 'rules'
$SkillsSrc = Join-Path $RepoRoot 'skills'
$PiExtensionsSrc = Join-Path $RepoRoot 'pi\extensions'
$PiThemesSrc = Join-Path $RepoRoot 'pi\themes'
$PiKeybindingsSrc = Join-Path $RepoRoot 'pi\keybindings.json'
$OpenCodeSrc = Join-Path $RepoRoot 'opencode'
$GeneratedMarker = 'Generated by ChekTek/ai scripts/update-config'
$AllowedTargets = @('claude', 'copilot', 'pi', 'codex', 'opencode')

$ClaudeRulesDest = Join-Path $HOME '.claude\rules'
$ClaudeSkillsDest = Join-Path $HOME '.claude\skills'
$CopilotSkillsDest = Join-Path $HOME '.copilot\skills'
$PiSkillsDest = Join-Path $HOME '.pi\agent\skills'
$PiExtensionsDest = Join-Path $HOME '.pi\agent\extensions'
$PiThemesDest = Join-Path $HOME '.pi\agent\themes'
$PiKeybindingsDest = Join-Path $HOME '.pi\agent\keybindings.json'
$PiRulesDest = Join-Path $HOME '.pi\agent\rules'
$PiLegacyRulesDest = Join-Path $HOME '.pi\agent\AGENTS.md'

if ($env:COPILOT_CLI_INSTRUCTIONS_DIR) {
    $CopilotInstructionsDest = $env:COPILOT_CLI_INSTRUCTIONS_DIR
}
else {
    $CopilotInstructionsDest = Join-Path $HOME '.copilot\instructions'
}

if ($env:CODEX_HOME) {
    $CodexRoot = $env:CODEX_HOME
}
else {
    $CodexRoot = Join-Path $HOME '.codex'
}
$CodexSkillsDest = Join-Path $CodexRoot 'skills'
$CodexRulesDest = Join-Path $CodexRoot 'AGENTS.md'
$OpenCodeRoot = Join-Path $HOME '.config\opencode'
$OpenCodeSkillsDest = Join-Path $OpenCodeRoot 'skills'
$OpenCodeCommandsDest = Join-Path $OpenCodeRoot 'commands'
$OpenCodePluginsDest = Join-Path $OpenCodeRoot 'plugins'
$OpenCodeRulesDest = Join-Path $OpenCodeRoot 'rules'
$OpenCodeLegacyRulesDest = Join-Path $OpenCodeRoot 'AGENTS.md'
$OpenCodeContextManagerDest = Join-Path $OpenCodeRoot 'context-manager.ts'
$OpenCodeTuiPluginDest = Join-Path $OpenCodeRoot 'context-report-tui.ts'
$OpenCodeTuiConfigDest = Join-Path $OpenCodeRoot 'tui.jsonc'
# npm has only published through 0.2.0; v0.3.3 is the GitHub tag this setup pins.
$PiCursorSdkPackage = 'git:github.com/fitchmultz/pi-cursor-sdk@v0.3.3'
$PiCursorSdkInstall = Join-Path $HOME '.pi\agent\git\github.com\fitchmultz\pi-cursor-sdk'

function Get-TargetMetadata {
    param([string] $Path)

    $lines = @(Get-Content -LiteralPath $Path)
    if ($lines.Count -eq 0 -or $lines[0].TrimEnd("`r") -ne '---') {
        return [pscustomobject]@{ Present = $false; Value = $null }
    }

    $inMetadata = $false
    $found = $false
    $value = $null

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].TrimEnd("`r")

        if ($line -eq '---') { break }

        if (($line -match '^metadata:.*targets\s*:') -or
            (-not $inMetadata -and $line -match '^\s*targets\s*:')) {
            throw "invalid targets in ${Path}: put targets under metadata"
        }

        if ($line -match '^metadata:\s*$') {
            $inMetadata = $true
            continue
        }

        if ($line -match '^\S') { $inMetadata = $false }

        if ($inMetadata -and $line -match '^\s+targets\s*:\s*(.*)$') {
            if ($found) {
                throw "invalid targets in ${Path}: metadata.targets is defined more than once"
            }

            $found = $true
            $value = $Matches[1].Trim()
            if ($value.Length -ge 2) {
                $first = $value[0]
                $last = $value[$value.Length - 1]
                if (($first -eq '"' -and $last -eq '"') -or ($first -eq "'" -and $last -eq "'")) {
                    $value = $value.Substring(1, $value.Length - 2)
                }
            }
        }
    }

    return [pscustomobject]@{ Present = $found; Value = $value }
}

function Assert-ValidTargets {
    param([string] $Path)

    $metadata = Get-TargetMetadata $Path
    if (-not $metadata.Present) { return }
    if ([string]::IsNullOrWhiteSpace($metadata.Value)) {
        throw "invalid targets in ${Path}: metadata.targets cannot be empty"
    }

    $seen = @{}
    foreach ($part in $metadata.Value.Split(',')) {
        $target = $part.Trim()
        if ([string]::IsNullOrWhiteSpace($target)) {
            throw "invalid targets in ${Path}: empty target"
        }
        if ($AllowedTargets -notcontains $target) {
            throw "invalid targets in ${Path}: unknown target $target (allowed: claude, copilot, pi, codex, opencode)"
        }
        if ($seen.ContainsKey($target)) {
            throw "invalid targets in ${Path}: duplicate target $target"
        }
        $seen[$target] = $true
    }
}

function Test-SourceTargets {
    param(
        [string] $Path,
        [string] $Target
    )

    $metadata = Get-TargetMetadata $Path
    if (-not $metadata.Present) { return $true }
    $targets = @($metadata.Value.Split(',') | ForEach-Object { $_.Trim() })
    return $targets -contains $Target
}

function Assert-ValidSources {
    if (-not (Test-Path -LiteralPath $RulesSrc -PathType Container)) {
        throw "missing source directory: $RulesSrc"
    }
    if (-not (Test-Path -LiteralPath $SkillsSrc -PathType Container)) {
        throw "missing source directory: $SkillsSrc"
    }
    if (-not (Test-Path -LiteralPath $PiExtensionsSrc -PathType Container)) {
        throw "missing source directory: $PiExtensionsSrc"
    }
    if (-not (Test-Path -LiteralPath $PiThemesSrc -PathType Container)) {
        throw "missing source directory: $PiThemesSrc"
    }
    if (-not (Test-Path -LiteralPath $PiKeybindingsSrc -PathType Leaf)) {
        throw "missing source file: $PiKeybindingsSrc"
    }
    if (-not (Test-Path -LiteralPath (Join-Path $OpenCodeSrc 'plugins') -PathType Container)) {
        throw "missing source directory: $(Join-Path $OpenCodeSrc 'plugins')"
    }
    foreach ($source in @('context-manager.ts', 'context-report-tui.ts', 'tui.jsonc')) {
        $path = Join-Path $OpenCodeSrc $source
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            throw "missing source file: $path"
        }
    }

    Get-ChildItem -LiteralPath $SkillsSrc -Force | ForEach-Object {
        $skillFile = Join-Path $_.FullName 'SKILL.md'
        if (-not $_.PSIsContainer -or -not (Test-Path -LiteralPath $skillFile -PathType Leaf)) {
            throw "invalid skill source: $($_.FullName) must be a directory containing SKILL.md"
        }
        Assert-ValidTargets $skillFile
    }

    Get-ChildItem -LiteralPath $RulesSrc -Filter '*.md' -File -Recurse | ForEach-Object {
        Assert-ValidTargets $_.FullName
    }
}

function Get-ExistingItem {
    param([string] $Path)
    return (Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue)
}

function Test-OwnedLink {
    param([string] $Path)

    $item = Get-ExistingItem $Path
    if (-not $item -or -not $item.LinkType) { return $false }

    $repoPrefix = $RepoRoot.TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar
    foreach ($rawTarget in @($item.Target)) {
        if (-not $rawTarget) { continue }
        if ([System.IO.Path]::IsPathRooted($rawTarget)) {
            $fullTarget = [System.IO.Path]::GetFullPath($rawTarget)
        }
        else {
            $fullTarget = [System.IO.Path]::GetFullPath((Join-Path $item.DirectoryName $rawTarget))
        }
        if ($fullTarget.StartsWith($repoPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }

    return $false
}

function Remove-LinkItem {
    param([System.IO.FileSystemInfo] $Item)
    # Remove-Item -Recurse on a directory link can delete its target on Windows
    # PowerShell. FileSystemInfo.Delete() removes only the link itself.
    $Item.Delete()
}

function Test-GeneratedFile {
    param([string] $Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    return [bool](Select-String -LiteralPath $Path -Pattern $GeneratedMarker -SimpleMatch -Quiet)
}

function Assert-GlobalRulesDestination {
    param(
        [string] $TargetName,
        [string] $Destination,
        [string] $Label
    )

    if (-not (Test-Path -LiteralPath $Destination) -or (Test-GeneratedFile $Destination)) {
        return
    }

    $hasRules = Get-ChildItem -LiteralPath $RulesSrc -Filter '*.md' -File -Recurse |
        Where-Object { Test-SourceTargets $_.FullName $TargetName } |
        Select-Object -First 1
    if (-not $hasRules) { return }

    throw "cannot generate ${Label}: $Destination already exists and is not managed by this repo. Move its contents into rules/ or remove it, then run this script again"
}

function Get-CleanTargets {
    @(
        @{ Dir = $ClaudeRulesDest; Label = 'claude/rules' }
        @{ Dir = $ClaudeSkillsDest; Label = 'claude/skills' }
        @{ Dir = $CopilotSkillsDest; Label = 'copilot/skills' }
        @{ Dir = $CopilotInstructionsDest; Label = 'copilot/instructions' }
        @{ Dir = $PiSkillsDest; Label = 'pi/skills' }
        @{ Dir = $PiExtensionsDest; Label = 'pi/extensions' }
        @{ Dir = $PiThemesDest; Label = 'pi/themes' }
        @{ Dir = $PiRulesDest; Label = 'pi/rules' }
        @{ Dir = $CodexSkillsDest; Label = 'codex/skills' }
        @{ Dir = $OpenCodeSkillsDest; Label = 'opencode/skills' }
        @{ Dir = $OpenCodeCommandsDest; Label = 'opencode/commands' }
        @{ Dir = $OpenCodePluginsDest; Label = 'opencode/plugins' }
        @{ Dir = $OpenCodeRulesDest; Label = 'opencode/rules' }
    )
}

function Invoke-Clean {
    $entries = @(
        foreach ($target in Get-CleanTargets) {
            if (-not (Test-Path -LiteralPath $target.Dir -PathType Container)) { continue }
            Get-ChildItem -LiteralPath $target.Dir -Force | ForEach-Object {
                if ($target.Label -eq 'codex/skills' -and $_.Name -eq '.system') { return }
                [pscustomobject]@{
                    Name = "$($target.Label)/$($_.Name)"
                    Path = $_.FullName
                }
            }
        }

        foreach ($generated in @(
            @{ Path = $PiLegacyRulesDest; Label = 'pi/AGENTS.md' }
            @{ Path = $CodexRulesDest; Label = 'codex/AGENTS.md' }
            @{ Path = $OpenCodeLegacyRulesDest; Label = 'opencode/AGENTS.md' }
        )) {
            if (Test-GeneratedFile $generated.Path) {
                [pscustomobject]@{ Name = $generated.Label; Path = $generated.Path }
            }
        }

        foreach ($extension in @(
            @{ Path = $OpenCodeContextManagerDest; Label = 'opencode/context-manager.ts' }
            @{ Path = $OpenCodeTuiPluginDest; Label = 'opencode/context-report-tui.ts' }
            @{ Path = $OpenCodeTuiConfigDest; Label = 'opencode/tui.jsonc' }
        )) {
            if ((Test-OwnedLink $extension.Path) -or (Test-GeneratedFile $extension.Path)) {
                [pscustomobject]@{ Name = $extension.Label; Path = $extension.Path }
            }
        }

        if (Test-OwnedLink $PiKeybindingsDest) {
            [pscustomobject]@{ Name = 'pi/keybindings.json'; Path = $PiKeybindingsDest }
        }
    )

    if ($entries.Count -eq 0) {
        Write-Host 'clean: nothing to remove'
        return
    }

    Write-Host "clean: permanently removing $($entries.Count) item(s):"
    $entries | ForEach-Object { Write-Host "  $($_.Name)" }

    if (-not $Yes) {
        $reply = Read-Host 'Continue? [y/N]'
        if ($reply -notmatch '^(y|yes)$') {
            Write-Host 'clean: aborted'
            exit 1
        }
    }

    foreach ($entry in $entries) {
        $item = Get-ExistingItem $entry.Path
        if ($item -and $item.LinkType) {
            Remove-LinkItem $item
        }
        elseif ($item) {
            Remove-Item -LiteralPath $entry.Path -Recurse -Force
        }
        Write-Host "removed: $($entry.Name)"
    }
}

function Remove-OwnedLink {
    param(
        [string] $Path,
        [string] $Label
    )

    if (-not (Test-OwnedLink $Path)) { return }
    Remove-LinkItem (Get-ExistingItem $Path)
    Write-Host "removed: $Label"
}

function Publish-Skills {
    param(
        [string] $Dest,
        [string] $Label,
        [string] $TargetName
    )

    New-Item -ItemType Directory -Force $Dest | Out-Null

    Get-ChildItem -LiteralPath $SkillsSrc -Directory | ForEach-Object {
        $skillFile = Join-Path $_.FullName 'SKILL.md'
        $target = Join-Path $Dest $_.Name

        if (-not (Test-SourceTargets $skillFile $TargetName)) {
            Remove-OwnedLink $target "$Label/$($_.Name)"
            return
        }

        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: $Label/$($_.Name)"
            return
        }

        if ($existing) {
            Remove-LinkItem $existing
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "updated: $Label/$($_.Name)"
        }
        else {
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: $Label/$($_.Name)"
        }
    }

    Get-ChildItem -LiteralPath $Dest -Force | ForEach-Object {
        if (-not $_.LinkType -or -not (Test-OwnedLink $_.FullName)) { return }
        $linkExists = @($_.Target) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($linkExists) { return }
        Remove-LinkItem $_
        Write-Host "removed stale: $Label/$($_.Name)"
    }
}

function Install-PiExtensionDependencies {
    param([System.IO.DirectoryInfo] $Extension)

    $packagePath = Join-Path $Extension.FullName 'package.json'
    if (-not (Test-Path -LiteralPath $packagePath -PathType Leaf)) { return }

    $pnpmLockPath = Join-Path $Extension.FullName 'pnpm-lock.yaml'
    if (Test-Path -LiteralPath $pnpmLockPath -PathType Leaf) {
        if (-not (Get-Command pnpm -ErrorAction SilentlyContinue)) {
            throw "cannot install dependencies for $($Extension.FullName): pnpm is not on PATH"
        }

        & pnpm install --dir "$($Extension.FullName)" --prod --frozen-lockfile --ignore-scripts
        if ($LASTEXITCODE -ne 0) {
            throw "failed to install dependencies for $($Extension.FullName)"
        }

        return
    }

    if (-not (Get-Command npm -ErrorAction SilentlyContinue)) {
        throw "cannot install dependencies for $($Extension.FullName): npm is not on PATH"
    }

    & npm install --prefix "$($Extension.FullName)" --omit=dev --ignore-scripts --no-audit --no-fund
    if ($LASTEXITCODE -ne 0) {
        throw "failed to install dependencies for $($Extension.FullName)"
    }
}

function Publish-PiThemes {
    New-Item -ItemType Directory -Force $PiThemesDest | Out-Null

    Get-ChildItem -LiteralPath $PiThemesSrc -Filter '*.json' -File | ForEach-Object {
        $target = Join-Path $PiThemesDest $_.Name
        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: pi/themes/$($_.Name)"
            return
        }

        if ($existing) {
            Remove-LinkItem $existing
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "updated: pi/themes/$($_.Name)"
        }
        else {
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: pi/themes/$($_.Name)"
        }
    }

    Get-ChildItem -LiteralPath $PiThemesDest -Force | ForEach-Object {
        if (-not $_.LinkType -or -not (Test-OwnedLink $_.FullName)) { return }
        $linkExists = @($_.Target) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($linkExists) { return }
        Remove-LinkItem $_
        Write-Host "removed stale: pi/themes/$($_.Name)"
    }
}

function Publish-PiKeybindings {
    New-Item -ItemType Directory -Force (Split-Path -Parent $PiKeybindingsDest) | Out-Null
    $existing = Get-ExistingItem $PiKeybindingsDest
    if ($existing -and -not (Test-OwnedLink $PiKeybindingsDest)) {
        Write-Host 'skip existing: pi/keybindings.json'
        return
    }

    if ($existing) {
        Remove-LinkItem $existing
        New-Item -ItemType SymbolicLink -Path $PiKeybindingsDest -Target $PiKeybindingsSrc | Out-Null
        Write-Host 'updated: pi/keybindings.json'
    }
    else {
        New-Item -ItemType SymbolicLink -Path $PiKeybindingsDest -Target $PiKeybindingsSrc | Out-Null
        Write-Host 'linked: pi/keybindings.json'
    }
}

function Publish-PiExtensions {
    New-Item -ItemType Directory -Force $PiExtensionsDest | Out-Null

    Get-ChildItem -LiteralPath $PiExtensionsSrc | ForEach-Object {
        if ($_.PSIsContainer) { Install-PiExtensionDependencies $_ }
        $target = Join-Path $PiExtensionsDest $_.Name
        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: pi/extensions/$($_.Name)"
            return
        }

        if ($existing) {
            Remove-LinkItem $existing
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "updated: pi/extensions/$($_.Name)"
        }
        else {
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: pi/extensions/$($_.Name)"
        }
    }

    Get-ChildItem -LiteralPath $PiExtensionsDest -Force | ForEach-Object {
        if (-not $_.LinkType -or -not (Test-OwnedLink $_.FullName)) { return }
        $linkExists = @($_.Target) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($linkExists) { return }
        Remove-LinkItem $_
        Write-Host "removed stale: pi/extensions/$($_.Name)"
    }
}

function Install-PiCursorSdkPackage {
    if (-not (Get-Command pi -ErrorAction SilentlyContinue)) {
        Write-Host "skip ${PiCursorSdkPackage}: pi is not on PATH"
        return
    }

    $settingsPath = Join-Path $HOME '.pi\agent\settings.json'
    if ((Test-Path -LiteralPath $PiCursorSdkInstall) -and (Test-Path -LiteralPath $settingsPath -PathType Leaf)) {
        $settingsText = Get-Content -LiteralPath $settingsPath -Raw
        if ($settingsText -like "*${PiCursorSdkPackage}*") {
            Write-Host "already installed: $PiCursorSdkPackage"
            return
        }
    }

    & pi install $PiCursorSdkPackage
    if ($LASTEXITCODE -ne 0) {
        throw "failed to install $PiCursorSdkPackage"
    }
}

function Publish-OpenCodeExtensions {
    New-Item -ItemType Directory -Force $OpenCodePluginsDest | Out-Null

    Get-ChildItem -LiteralPath (Join-Path $OpenCodeSrc 'plugins') | ForEach-Object {
        $target = Join-Path $OpenCodePluginsDest $_.Name
        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: opencode/plugins/$($_.Name)"
            return
        }
        if ($existing) { Remove-LinkItem $existing }
        New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
        Write-Host "$(if ($existing) { 'updated' } else { 'linked' }): opencode/plugins/$($_.Name)"
    }

    Get-ChildItem -LiteralPath $OpenCodePluginsDest -Force | ForEach-Object {
        if (-not $_.LinkType -or -not (Test-OwnedLink $_.FullName)) { return }
        $sourcePrefix = (Join-Path $OpenCodeSrc 'plugins').TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar
        $ownedSource = @($_.Target) | Where-Object {
            $_ -and ([System.IO.Path]::GetFullPath($_)).StartsWith($sourcePrefix, [System.StringComparison]::OrdinalIgnoreCase)
        }
        if (-not $ownedSource -or (Test-Path -LiteralPath $ownedSource[0])) { return }
        Remove-LinkItem $_
        Write-Host "removed stale: opencode/plugins/$($_.Name)"
    }

    foreach ($file in @('context-manager.ts', 'context-report-tui.ts')) {
        $source = Join-Path $OpenCodeSrc $file
        $target = Join-Path $OpenCodeRoot $file
        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: opencode/$file"
            continue
        }
        if ($existing) { Remove-LinkItem $existing }
        New-Item -ItemType SymbolicLink -Path $target -Target $source | Out-Null
        Write-Host "$(if ($existing) { 'updated' } else { 'linked' }): opencode/$file"
    }

    Write-GeneratedFile $OpenCodeTuiConfigDest @(Get-Content -LiteralPath (Join-Path $OpenCodeSrc 'tui.jsonc')) 'opencode/tui.jsonc'

    @((Get-ExistingItem $OpenCodeContextManagerDest), (Get-ExistingItem $OpenCodeTuiPluginDest)) |
        Where-Object { $_ -and $_.LinkType -and (Test-OwnedLink $_.FullName) } |
        ForEach-Object {
            $linkExists = @($_.Target) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
            if ($linkExists) { return }
            $name = $_.FullName.Substring($OpenCodeRoot.Length).TrimStart('\', '/').Replace('\', '/')
            Remove-LinkItem $_
            Write-Host "removed stale: opencode/$name"
        }
}

function Get-RelativePath {
    param(
        [string] $Root,
        [string] $Path
    )

    $prefix = $Root.TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar
    if (-not $Path.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "$Path is not under $Root"
    }
    return $Path.Substring($prefix.Length).Replace('\', '/')
}

function Remove-StaleRuleLinks {
    param(
        [string] $Dest,
        [string] $Label
    )

    if (-not (Test-Path -LiteralPath $Dest -PathType Container)) { return }

    Get-ChildItem -LiteralPath $Dest -Force -Recurse | ForEach-Object {
        if (-not $_.LinkType -or -not (Test-OwnedLink $_.FullName)) { return }
        $linkExists = @($_.Target) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($linkExists) { return }
        $relative = Get-RelativePath $Dest $_.FullName
        Remove-LinkItem $_
        Write-Host "removed stale: $Label/$relative"
    }
}

function Publish-Rules {
    param(
        [string] $Dest,
        [string] $Label,
        [string] $TargetName
    )

    New-Item -ItemType Directory -Force $Dest | Out-Null
    Remove-StaleRuleLinks $Dest $Label

    Get-ChildItem -LiteralPath $RulesSrc -Filter '*.md' -File -Recurse | ForEach-Object {
        $relative = Get-RelativePath $RulesSrc $_.FullName
        $target = Join-Path $Dest $relative

        if (-not (Test-SourceTargets $_.FullName $TargetName)) {
            Remove-OwnedLink $target "$Label/$relative"
            return
        }

        New-Item -ItemType Directory -Force (Split-Path -Parent $target) | Out-Null
        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: $Label/$relative"
            return
        }

        if ($existing) {
            Remove-LinkItem $existing
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "updated: $Label/$relative"
        }
        else {
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: $Label/$relative"
        }
    }

    Remove-StaleRuleLinks $Dest $Label
}

function Test-GeneratedFileWritable {
    param([string] $Target)
    return -not (Test-Path -LiteralPath $Target) -or (Test-GeneratedFile $Target)
}

function Write-GeneratedFile {
    param(
        [string] $Target,
        [string[]] $Lines,
        [string] $Label
    )

    if (-not (Test-GeneratedFileWritable $Target)) {
        Write-Host "skip existing: $Label"
        return
    }

    New-Item -ItemType Directory -Force (Split-Path -Parent $Target) | Out-Null
    $content = ($Lines -join [Environment]::NewLine) + [Environment]::NewLine
    Set-Content -LiteralPath $Target -Value $content -NoNewline -Encoding UTF8
    Write-Host "generated: $Label"
}

function Get-CopilotInstructionPath {
    param([System.IO.FileInfo] $Rule)

    $relative = Get-RelativePath $RulesSrc $Rule.FullName
    $name = [System.IO.Path]::ChangeExtension($relative, $null).Replace('\', '-').Replace('/', '-')
    return (Join-Path $CopilotInstructionsDest "$name.instructions.md")
}

function Convert-RuleToCopilotInstruction {
    param([System.IO.FileInfo] $Rule)

    $target = Get-CopilotInstructionPath $Rule
    if (-not (Test-SourceTargets $Rule.FullName 'copilot')) {
        if (Test-GeneratedFile $target) {
            Remove-Item -LiteralPath $target -Force
            Write-Host "removed: copilot/instructions/$([System.IO.Path]::GetFileName($target))"
        }
        return
    }

    $relative = Get-RelativePath $RulesSrc $Rule.FullName
    $name = [System.IO.Path]::ChangeExtension($relative, $null).Replace('\', '-').Replace('/', '-')
    $lines = @(Get-Content -LiteralPath $Rule.FullName)
    $descriptions = @()
    $paths = @()
    $bodyStart = 0
    $inPaths = $false

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line -eq '---') {
            $bodyStart = $i + 1
            break
        }
        if ($line -match '^description:') {
            $descriptions += $line
            $inPaths = $false
            continue
        }
        if ($line -match '^paths:\s*$') {
            $inPaths = $true
            continue
        }
        if ($inPaths -and $line -match '^\s*-\s*(.+)$') {
            $paths += $Matches[1]
            continue
        }
        $inPaths = $false
    }

    $output = @('---')
    $output += $descriptions
    $output += "name: `"$name`""
    if ($paths.Count -eq 1) {
        $output += "applyTo: $($paths[0])"
    }
    elseif ($paths.Count -gt 1) {
        $output += 'applyTo:'
        $output += ($paths | ForEach-Object { "    - $_" })
    }
    $output += '---'
    $output += "<!-- $GeneratedMarker from rules/$relative -->"
    $output += ''
    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }

    Write-GeneratedFile $target $output "copilot/instructions/$([System.IO.Path]::GetFileName($target))"
}

function Remove-StaleGeneratedInstructions {
    if (-not (Test-Path -LiteralPath $CopilotInstructionsDest -PathType Container)) { return }

    Get-ChildItem -LiteralPath $CopilotInstructionsDest -Filter '*.md' -File | ForEach-Object {
        if (-not (Test-GeneratedFile $_.FullName)) { return }
        $match = Select-String -LiteralPath $_.FullName -Pattern "$([regex]::Escape($GeneratedMarker)) from (.+) -->" |
            Select-Object -First 1
        if (-not $match) { return }
        $sourceRel = $match.Matches[0].Groups[1].Value
        if (Test-Path -LiteralPath (Join-Path $RepoRoot $sourceRel)) { return }
        Remove-Item -LiteralPath $_.FullName -Force
        Write-Host "removed stale: copilot/instructions/$($_.Name)"
    }
}

function Generate-CopilotInstructions {
    Get-ChildItem -LiteralPath $RulesSrc -Filter '*.md' -File -Recurse | ForEach-Object {
        Convert-RuleToCopilotInstruction $_
    }
    Remove-StaleGeneratedInstructions
}

function Convert-SkillToOpenCodeCommand {
    param([System.IO.DirectoryInfo] $Skill)

    $source = Join-Path $Skill.FullName 'SKILL.md'
    $target = Join-Path $OpenCodeCommandsDest "$($Skill.Name).md"
    if (-not (Test-SourceTargets $source 'opencode') -or -not (Test-UserOnlySkill $source)) {
        if (Test-GeneratedFile $target) {
            Remove-Item -LiteralPath $target -Force
            Write-Host "removed: opencode/commands/$($Skill.Name).md"
        }
        return
    }

    $lines = @(Get-Content -LiteralPath $source)
    $bodyStart = 0
    if ($lines.Count -gt 0 -and $lines[0] -eq '---') {
        for ($i = 1; $i -lt $lines.Count; $i++) {
            if ($lines[$i] -eq '---') {
                $bodyStart = $i + 1
                break
            }
        }
    }

    $output = @(
        '---'
        "description: `"Run the $($Skill.Name) skill.`""
        '---'
        "<!-- $GeneratedMarker from skills/$($Skill.Name)/SKILL.md -->"
        ''
    )
    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }
    Write-GeneratedFile $target $output "opencode/commands/$($Skill.Name).md"
}

function Test-UserOnlySkill {
    param([string] $Path)

    $lines = @(Get-Content -LiteralPath $Path)
    if ($lines.Count -eq 0 -or $lines[0] -ne '---') { return $false }

    for ($i = 1; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -eq '---') { break }
        if ($lines[$i] -match '^disable-model-invocation:\s*true\s*$') { return $true }
    }
    return $false
}

function Publish-OpenCodeSkills {
    New-Item -ItemType Directory -Force $OpenCodeSkillsDest | Out-Null

    Get-ChildItem -LiteralPath $SkillsSrc -Directory | ForEach-Object {
        $skillFile = Join-Path $_.FullName 'SKILL.md'
        $target = Join-Path $OpenCodeSkillsDest $_.Name
        if (-not (Test-SourceTargets $skillFile 'opencode') -or (Test-UserOnlySkill $skillFile)) {
            Remove-OwnedLink $target "opencode/skills/$($_.Name)"
            return
        }

        $existing = Get-ExistingItem $target
        if ($existing -and -not (Test-OwnedLink $target)) {
            Write-Host "skip existing: opencode/skills/$($_.Name)"
            return
        }
        if ($existing) {
            Remove-LinkItem $existing
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "updated: opencode/skills/$($_.Name)"
        }
        else {
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: opencode/skills/$($_.Name)"
        }
    }
}

function Remove-StaleOpenCodeCommands {
    if (-not (Test-Path -LiteralPath $OpenCodeCommandsDest -PathType Container)) { return }

    Get-ChildItem -LiteralPath $OpenCodeCommandsDest -Filter '*.md' -File | ForEach-Object {
        if (-not (Test-GeneratedFile $_.FullName)) { return }
        $match = Select-String -LiteralPath $_.FullName -Pattern "$([regex]::Escape($GeneratedMarker)) from (.+) -->" |
            Select-Object -First 1
        if (-not $match) { return }
        $sourceRel = $match.Matches[0].Groups[1].Value
        if (Test-Path -LiteralPath (Join-Path $RepoRoot $sourceRel)) { return }
        Remove-Item -LiteralPath $_.FullName -Force
        Write-Host "removed stale: opencode/commands/$($_.Name)"
    }
}

function Generate-OpenCodeCommands {
    Get-ChildItem -LiteralPath $SkillsSrc -Directory | ForEach-Object {
        Convert-SkillToOpenCodeCommand $_
    }
    Remove-StaleOpenCodeCommands
}

function Remove-OuterQuotes {
    param([string] $Value)

    $trimmed = $Value.Trim()
    if ($trimmed.Length -lt 2) { return $trimmed }
    if (($trimmed[0] -eq '"' -and $trimmed[$trimmed.Length - 1] -eq '"') -or
        ($trimmed[0] -eq "'" -and $trimmed[$trimmed.Length - 1] -eq "'")) {
        return $trimmed.Substring(1, $trimmed.Length - 2)
    }
    return $trimmed
}

function Convert-RuleToGlobalLines {
    param([System.IO.FileInfo] $Rule)

    $relative = Get-RelativePath $RulesSrc $Rule.FullName
    $lines = @(Get-Content -LiteralPath $Rule.FullName)
    $paths = @()
    $bodyStart = 0
    $inPaths = $false

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line -eq '---') {
            $bodyStart = $i + 1
            break
        }
        if ($line -match '^description:\s*(.*)$') {
            $inPaths = $false
            continue
        }
        if ($line -match '^paths:\s*$') {
            $inPaths = $true
            continue
        }
        if ($inPaths -and $line -match '^\s*-\s*(.+)$') {
            $paths += (Remove-OuterQuotes $Matches[1])
            continue
        }
        $inPaths = $false
    }

    $output = @('', "<!-- Source: rules/$relative -->")
    if ($paths.Count -eq 0) {
        $output += '**Applies to:** All files and tasks.'
    }
    else {
        $formattedPaths = ($paths | ForEach-Object { "``$_``" }) -join ', '
        $output += "**Applies to paths:** $formattedPaths"
    }
    $output += ''
    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }
    return $output
}

function Write-GlobalRulesFile {
    param(
        [string] $Target,
        [string[]] $Lines,
        [string] $Label
    )

    if ((Test-Path -LiteralPath $Target) -and -not (Test-GeneratedFile $Target)) {
        throw "cannot generate ${Label}: $Target already exists and is not managed by this repo. Move its contents into rules/ or remove it, then run this script again"
    }

    New-Item -ItemType Directory -Force (Split-Path -Parent $Target) | Out-Null
    $content = ($Lines -join [Environment]::NewLine) + [Environment]::NewLine
    Set-Content -LiteralPath $Target -Value $content -NoNewline -Encoding UTF8
    Write-Host "generated: $Label"
}

function Generate-GlobalRules {
    param(
        [string] $TargetName,
        [string] $Destination,
        [string] $Label
    )

    $rules = @(
        Get-ChildItem -LiteralPath $RulesSrc -Filter '*.md' -File -Recurse |
            Sort-Object FullName |
            Where-Object { Test-SourceTargets $_.FullName $TargetName }
    )

    if ($rules.Count -eq 0) {
        if (Test-GeneratedFile $Destination) {
            Remove-Item -LiteralPath $Destination -Force
            Write-Host "removed: $Label"
        }
        return
    }

    $output = @(
        "<!-- $GeneratedMarker from rules/ -->"
        '# User Rules'
        ''
        'These are global user instructions. Rules without path patterns always apply.'
        'Rules with path patterns apply only when work affects matching files. Follow all'
        'applicable rules, with more specific rules taking precedence.'
    )

    foreach ($rule in $rules) {
        $output += Convert-RuleToGlobalLines $rule
    }

    Write-GlobalRulesFile $Destination $output $Label
}

Assert-ValidSources
Assert-GlobalRulesDestination 'codex' $CodexRulesDest 'codex/AGENTS.md'

if ($Clean) { Invoke-Clean }

Publish-Skills $ClaudeSkillsDest 'claude/skills' 'claude'
Publish-Skills $CopilotSkillsDest 'copilot/skills' 'copilot'
Publish-Skills $PiSkillsDest 'pi/skills' 'pi'
Publish-Skills $CodexSkillsDest 'codex/skills' 'codex'
Publish-PiExtensions
Install-PiCursorSdkPackage
Publish-PiThemes
Publish-PiKeybindings
Publish-Rules $ClaudeRulesDest 'claude/rules' 'claude'
Publish-Rules $PiRulesDest 'pi/rules' 'pi'
Publish-Rules $OpenCodeRulesDest 'opencode/rules' 'opencode'
if (Test-GeneratedFile $PiLegacyRulesDest) {
    Remove-Item -LiteralPath $PiLegacyRulesDest -Force
    Write-Host 'removed: pi/AGENTS.md'
}
Generate-CopilotInstructions
Generate-OpenCodeCommands
Publish-OpenCodeSkills
Publish-OpenCodeExtensions
Generate-GlobalRules 'codex' $CodexRulesDest 'codex/AGENTS.md'
if (Test-GeneratedFile $OpenCodeLegacyRulesDest) {
    Remove-Item -LiteralPath $OpenCodeLegacyRulesDest -Force
    Write-Host 'removed: opencode/AGENTS.md'
}
